import os
from typing import Dict, List, Optional, Any
from dataclasses import dataclass
import boto3
from botocore.exceptions import ClientError

@dataclass
class ReceiptItem:
    description: str
    quantity: Optional[str]
    unit_price: Optional[str]
    total_price: Optional[str]

@dataclass
class ReceiptData:
    merchant: Optional[str]
    tax: Optional[str]
    total: Optional[str]
    items: List[ReceiptItem]

def extract_receipt_data(image_path: str) -> ReceiptData:
    client = boto3.client(
        'textract',
        aws_access_key_id=os.environ.get('AWS_ACCESS_KEY_ID'),
        aws_secret_access_key=os.environ.get('AWS_SECRET_ACCESS_KEY'),
        region_name=os.environ.get('AWS_REGION', 'us-east-1')
    )

    with open(image_path, 'rb') as image_file:
        image_bytes = image_file.read()

    response = client.analyze_expense(Document={'Bytes': image_bytes})

    merchant = None
    tax = None
    total = None
    items = []

    for expense_doc in response['ExpenseDocuments']:
        for summary_field in expense_doc.get('SummaryFields', []):
            label = summary_field.get('Type', {}).get('Text', '').lower()
            value = summary_field.get('ValueDetection', {}).get('Text')

            if 'vendor' in label or 'merchant' in label:
                merchant = value
            elif 'tax' in label:
                tax = value
            elif 'total' in label:
                total = value

        for line_item_group in expense_doc.get('LineItemGroups', []):
            for line_item in line_item_group.get('LineItems', []):
                item_desc = None
                quantity = None
                unit_price = None
                item_total = None

                for expense_field in line_item.get('LineItemExpenseFields', []):
                    field_type = expense_field.get('Type', {}).get('Text', '').lower()
                    field_value = expense_field.get('ValueDetection', {}).get('Text')

                    if 'item' in field_type or 'description' in field_type:
                        item_desc = field_value
                    elif 'quantity' in field_type:
                        quantity = field_value
                    elif 'unit' in field_type:
                        unit_price = field_value
                    elif 'price' in field_type or 'amount' in field_type:
                        item_total = field_value

                if item_desc:
                    items.append(ReceiptItem(
                        description=item_desc,
                        quantity=quantity,
                        unit_price=unit_price,
                        total_price=item_total
                    ))

    return ReceiptData(
        merchant=merchant,
        tax=tax,
        total=total,
        items=items
    )
